.mega-menu {
  position: absolute; left: 50%; transform: translateX(-50%); top: calc(100% + 16px);
  width: min(980px, calc(100vw - 40px));
  background: #fff; color: var(--navy); border-radius: 14px; box-shadow: var(--shadow);
  padding: 26px; display: none; grid-template-columns: 1.4fr 1fr; gap: 28px;
}
.nav-item-services.open .mega-menu { display: grid; }
.mega-col h4 { margin: 0 0 12px; font-size: 13px; text-transform: uppercase; letter-spacing: 1px; color: var(--gray-500); }
.mega-list { display: grid; gap: 10px; }
.mega-list a { padding: 10px 12px; border-radius: 10px; background: var(--gray-50); font-weight: 600; }
.mega-list a:hover { background: var(--gray-100); }
.mobile-toggle { display: none; background: none; border: 0; color: #fff; font-size: 26px; }
.mobile-nav { display: none; background: var(--navy-2); color: #fff; padding: 10px 24px 20px; }
.mobile-section { border-top: 1px solid rgba(255,255,255,.12); }
