.section-light { background: var(--gray-50); }
.grid-3 { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 22px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 24px; }
.card { border: 1px solid var(--gray-200); border-radius: 14px; padding: 24px; background: #fff; }
.card h3 { margin: 0 0 8px; font-size: 1.2rem; }
.kicker { color: var(--teal); font-weight: 700; letter-spacing: .8px; text-transform: uppercase; font-size: 12px; margin-bottom: 10px; }
.section h2 { margin: 0 0 16px; font-size: clamp(1.7rem, 3.1vw, 2.7rem); }
.what-we-do { display: grid; grid-template-columns: 280px 1fr; gap: 26px; }
.tab-list button { width: 100%; text-align: left; border: 1px solid var(--gray-200); background: #fff; padding: 14px 16px; margin-bottom: 10px; border-radius: 10px; font-weight: 700; color: var(--navy); }
.tab-list button.active { background: var(--navy); color: #fff; border-color: var(--navy); }
.tab-panel { border: 1px solid var(--gray-200); border-radius: 14px; padding: 30px; background: #fff; min-height: 220px; }
.insight-card img { border-radius: 10px; height: 170px; width: 100%; object-fit: cover; margin-bottom: 12px; }
.insight-meta { font-size: 12px; text-transform: uppercase; color: var(--gray-500); letter-spacing: .7px; }
.footer { background: var(--navy); color: #d5deea; padding: 50px 0 30px; margin-top: 50px; }
.footer-grid { display: grid; grid-template-columns: 1.2fr 1fr 1fr; gap: 24px; }
.page-hero { position: relative; min-height: 42vh; display: flex; align-items: center; color: #fff; }
.page-hero::before { content: ""; position: absolute; inset: 0; background: linear-gradient(110deg, rgba(10,22,40,.92), rgba(10,22,40,.38)); }
.page-hero .hero-content { padding: 70px 0; }
.cap-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 20px; }
.cap-card { background: #fff; border: 1px solid var(--gray-200); border-radius: 12px; padding: 20px; }
.sidebar-list { border: 1px solid var(--gray-200); border-radius: 12px; padding: 18px; background: #fff; }
.sidebar-list a { display: block; padding: 10px 0; border-bottom: 1px solid var(--gray-100); font-weight: 600; color: var(--navy-2); }
.sidebar-list a:last-child { border-bottom: 0; }
.carousel { border-radius: 14px; overflow: hidden; border: 1px solid var(--gray-200); }
.carousel-track { display: flex; transition: transform .45s ease; }
.slide { min-width: 100%; padding: 28px; background: linear-gradient(140deg, #10213a, #1f3558); color: #f0f4fb; }
.carousel-controls { display: flex; gap: 10px; margin-top: 14px; }
.carousel-controls button { border: 1px solid var(--gray-200); background: #fff; padding: 8px 12px; border-radius: 999px; }
@media (max-width: 1024px) {
  .grid-3, .cap-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
}
@media (max-width: 860px) {
  .nav-links, .navbar .header-cta { display: none; }
  .mobile-toggle, .mobile-nav { display: block; }
  .grid-3, .grid-2, .what-we-do, .cap-grid, .footer-grid { grid-template-columns: 1fr; }
  .hero { min-height: 56vh; }
}
EOF

